window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-b71232a939d57586"]={"versions": [{"id": "FIG-b71232a939d57586", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Zustandsübergangstabelle / Zustandsübergangsmatrix (<em>Transition Request Table</em> bzw. <em>State Transition Table</em>) zur Spezifikation eines erweiterten endlichen Zustandsautomaten (<em>Extended Finite State Machine</em>, EFSM).</li>\n<li><strong>Funktionale Einordnung:</strong> Entwurfsmuster und Richtlinie innerhalb der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_EXP_InterfacesGuidelines</code>, R23-11) zur standardisierten, deklarativen Implementierung von Zustandsübergängen auf Applikations- und Service-Ebene. Es modelliert das Verhalten zustandsbehafteter Komponenten (z. B. Subsysteme wie Kamerasysteme), deren Betriebsmodi deterministisch von externen Netzwerk- oder Systemtriggern (z. B. Network Management / State Management) abhängen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Tabellenstruktur / Datenmodell:</strong></li>\n<li><code>Trigger Value</code>: Eingangsvektor / Stimulus, welcher den Zustandswechsel anfordert.</li>\n<li><code>Current State</code>: Vorbedingung / Quellzustand vor Eintreffen des Triggers.</li>\n<li><code>Next State</code>: Folgezustand / Zielzustand nach erfolgreicher Transition.</li>\n<li>*<em>Zustände (</em>States<em>):</em>*</li>\n<li><code>Off</code>: Inaktiver Ruhezustand des Subsystems.</li>\n<li><code>Camera Active</code>: Aktiver Betriebsmodus des Kamerasystems.</li>\n<li><em>Metamodell-Entsprechung:</em> Abgebildet über <code>ModeDeclarationGroup</code> bzw. <code>ModeDeclaration</code> oder anwendungsspezifische Aufzählungstypen (<code>enum class</code>).</li>\n<li><strong>Trigger-Entitäten:</strong></li>\n<li><code>Nh1_NoCom</code>: Trigger-Wert für „Network Handle 1 – No Communication“.</li>\n<li><code>Nh1_FullCom</code>: Trigger-Wert für „Network Handle 1 – Full Communication“.</li>\n<li><em>Schnittstellenbezug:</em> Eintreffende Anforderung über Service-Schnittstellen (<code>ara::com</code> Field-Set, Event oder Method Call) oder Network-Management-/State-Management-Signale.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Eindeutige deterministische Relation: Jedes Tupel aus <code>(Trigger Value, Current State)</code> wird auf genau einen <code>Next State</code> gemappt ($1:1$-Zuordnung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Auslöser (Trigger) & Pfade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Transition 1:</em> Befindet sich das System im Zustand <code>Off</code> und empfängt den Trigger <code>Nh1_NoCom</code>, erfolgt der Zustandswechsel nach <code>Camera Active</code>.</li>\n<li><em>Transition 2:</em> Befindet sich das System im Zustand <code>Camera Active</code> und empfängt den Trigger <code>Nh1_FullCom</code>, wechselt es zurück in den Zustand <code>Off</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronisations- & Ausführungscharakteristik:</strong></li>\n<li><strong>Asynchroner Empfang:</strong> Trigger treffen ereignisgesteuert (asynchron) über die Middleware-Schicht ein.</li>\n<li><strong>Synchrone Transition:</strong> Die TransitionRequestTable wird tabellenbasiert (z. B. Look-up) ausgewertet.</li>\n<li><strong>Undefinierte Zustände / Discard-Pfade:</strong> Trifft ein Trigger ein, der für den aktuellen Zustand nicht in der Tabelle definiert ist (z. B. <code>Nh1_FullCom</code> im Zustand <code>Off</code>), liegt ein ungültiger Übergang vor. Dieser erfordert einen definierten Fallback (Ignorieren, Reject-Meldung oder Exception/Logging).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus:</strong> Als Bestandteil der <code>EXP</code>-Serie (Explanation/Guidelines) ist das Pattern nicht unmittelbar funktional zwingend über SWS-Requirements normiert, definiert jedoch die empfohlene Architektur-Best-Practice für adaptive Applikationen und Service-Interfaces.</li>\n<li><strong>Implementierungs-Empfehlung (C++14/C++17):</strong></li>\n<li>Bevorzugung tabellengesteuerter Implementierungen (<code>std::array</code>, flache Lookup-Tabellen oder <code>constexpr</code>-Hashtabellen) gegenüber tief verschachtelten <code>switch-case</code>-Strukturen zur Gewährleistung von $O(1)$-Laufzeitverhalten, Determinisierung und Testbarkeit.</li>\n<li><strong>Vollständigkeit & Robustheit:</strong></li>\n<li>Embedded-Entwickler müssen für fehlende Tupel <code>(Trigger, State)</code> eine explizite Fehlerbehandlungsstrategie implementieren (z. B. Rückgabe eines Fehlercodes, Logging via <code>ara::log</code> oder Meldung an das Diagnosesystem / PHM).</li>\n<li><strong>Zusammenspiel mit Adaptive State Management:</strong></li>\n<li>Soll der Zustandsübergang Prozesse oder Ressourcengruppen aktivieren/deaktivieren, muss die Tabelle direkt an <code>ara::sm</code> (State Management) bzw. <code>ara::exec</code> (Execution Management) angebunden werden, um Funktionsgruppen (<em>Function Groups</em>) konsistent umzuschalten.</li>\n</ul>"}, {"id": "FIG-8e73a09b5413d9dd", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> Tabellarische Zustandsübergangstabelle / Zustandsübergangsmatrix (<em>Transition Request Table</em> bzw. <em>State Transition Table</em>) zur Spezifikation eines erweiterten endlichen Zustandsautomaten (<em>Extended Finite State Machine</em>, EFSM).</li>\n<li><strong>Funktionale Einordnung:</strong> Entwurfsmuster und Richtlinie innerhalb der AUTOSAR Adaptive Platform (<code>AUTOSAR_AP_EXP_InterfacesGuidelines</code>, R23-11) zur standardisierten, deklarativen Implementierung von Zustandsübergängen auf Applikations- und Service-Ebene. Es modelliert das Verhalten zustandsbehafteter Komponenten (z. B. Subsysteme wie Kamerasysteme), deren Betriebsmodi deterministisch von externen Netzwerk- oder Systemtriggern (z. B. Network Management / State Management) abhängen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Tabellenstruktur / Datenmodell:</strong></li>\n<li><code>Transition Request</code>: Eingangsvektor / Stimulus, welcher den Zustandswechsel anfordert.</li>\n<li><code>Current State</code>: Vorbedingung / Quellzustand vor Eintreffen des Triggers.</li>\n<li><code>Next State</code>: Folgezustand / Zielzustand nach erfolgreicher Transition.</li>\n<li>*<em>Zustände (</em>States<em>):</em>*</li>\n<li><code>Off</code>: Inaktiver Ruhezustand des Subsystems.</li>\n<li><code>Camera Active</code>: Aktiver Betriebsmodus des Kamerasystems.</li>\n<li><em>Metamodell-Entsprechung:</em> Abgebildet über <code>ModeDeclarationGroup</code> bzw. <code>ModeDeclaration</code> oder anwendungsspezifische Aufzählungstypen (<code>enum class</code>).</li>\n<li><strong>Trigger-Entitäten:</strong></li>\n<li><code>Nh1_FullCom</code>: Anforderungswert für „Network Handle 1 – Full Communication“.</li>\n<li><code>Nh1_NoCom</code>: Anforderungswert für „Network Handle 1 – No Communication“.</li>\n<li><em>Schnittstellenbezug:</em> Eintreffende Anforderung über Service-Schnittstellen (<code>ara::com</code> Field-Set, Event oder Method Call) oder Network-Management-/State-Management-Signale.</li>\n<li><strong>Beziehungen & Kardinalitäten:</strong></li>\n<li>Eindeutige deterministische Relation: Jedes Tupel aus <code>(Transition Request, Current State)</code> wird auf genau einen <code>Next State</code> gemappt ($1:1$-Zuordnung).</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li><strong>Auslöser (Trigger) & Pfade:</strong></li>\n</ul>\n<ol class=\"fig-list\">\n<li><em>Transition 1:</em> Befindet sich das System im Zustand <code>Off</code> und empfängt die Anforderung <code>Nh1_FullCom</code>, erfolgt der Zustandswechsel nach <code>Camera Active</code>.</li>\n<li><em>Transition 2:</em> Befindet sich das System im Zustand <code>Camera Active</code> und empfängt die Anforderung <code>Nh1_NoCom</code>, wechselt es zurück in den Zustand <code>Off</code>.</li>\n</ol>\n<ul class=\"fig-list\">\n<li><strong>Synchronisations- & Ausführungscharakteristik:</strong></li>\n<li><strong>Asynchroner Empfang:</strong> Trigger bzw. Requests treffen ereignisgesteuert (asynchron) über die Middleware-Schicht ein.</li>\n<li><strong>Synchrone Transition:</strong> Die TransitionRequestTable wird tabellenbasiert (z. B. Look-up) ausgewertet.</li>\n<li><strong>Undefinierte Zustände / Discard-Pfade:</strong> Trifft eine Anforderung ein, die für den aktuellen Zustand nicht in der Tabelle definiert ist (z. B. <code>Nh1_NoCom</code> im Zustand <code>Off</code>), liegt ein ungültiger Übergang vor. Dieser erfordert einen definierten Fallback (Ignorieren, Reject-Meldung oder Exception/Logging).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Dokumentenstatus:</strong> Als Bestandteil der <code>EXP</code>-Serie (Explanation/Guidelines) ist das Pattern nicht unmittelbar funktional zwingend über SWS-Requirements normiert, definiert jedoch die empfohlene Architektur-Best-Practice für adaptive Applikationen und Service-Interfaces.</li>\n<li><strong>Implementierungs-Empfehlung (C++14/C++17):</strong></li>\n<li>Bevorzugung tabellengesteuerter Implementierungen (<code>std::array</code>, flache Lookup-Tabellen oder <code>constexpr</code>-Hashtabellen) gegenüber tief verschachtelten <code>switch-case</code>-Strukturen zur Gewährleistung von $O(1)$-Laufzeitverhalten, Determinisierung und Testbarkeit.</li>\n<li><strong>Vollständigkeit & Robustheit:</strong></li>\n<li>Embedded-Entwickler müssen für fehlende Tupel <code>(Trigger, State)</code> eine explizite Fehlerbehandlungsstrategie implementieren (z. B. Rückgabe eines Fehlercodes, Logging via <code>ara::log</code> oder Meldung an das Diagnosesystem / PHM).</li>\n<li><strong>Zusammenspiel mit Adaptive State Management:</strong></li>\n<li>Soll der Zustandsübergang Prozesse oder Ressourcengruppen aktivieren/deaktivieren, muss die Tabelle direkt an <code>ara::sm</code> (State Management) bzw. <code>ara::exec</code> (Execution Management) angebunden werden, um Funktionsgruppen (<em>Function Groups</em>) konsistent umzuschalten.</li>\n</ul>"}], "trans": [{"from": "FIG-b71232a939d57586", "to": "FIG-8e73a09b5413d9dd", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Spalte <code>Trigger Value</code>: Umbenannt zu <code>Transition Request</code>.</li>\n<li>Transition <code>Off</code> -> <code>Camera Active</code>: Auslöser von <code>Nh1_NoCom</code> zu <code>Nh1_FullCom</code> geändert.</li>\n<li>Transition <code>Camera Active</code> -> <code>Off</code>: Auslöser von <code>Nh1_FullCom</code> zu <code>Nh1_NoCom</code> geändert.</li>\n<li>Tabellenlayout: Entfernung der leeren Zwischenzeile unterhalb des Tabellenkopfs sowie Neugestaltung der Kopfzeile.</li>\n</ul>"}]};
